// Golden values were generated by the pinned reference with its compressed-rank
// parser repaired (and checked against Anthropic JS), independently
// of this implementation. Include metadata, Unicode normalization and tools.
func TestSub2APIMeteringReferenceFixtures(t *testing.T) {
	raw, err := os.ReadFile("testdata/sub2api-metering.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixtures struct {
		Texts []struct {
			Text   string
			Tokens int
		}
		Requests []struct {
			Request json.RawMessage
			Tokens  int
		}
	}
	if err := json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatal(err)
	}
	for i, c := range fixtures.Texts {
		if got := estimateApproxTokens(c.Text); got != c.Tokens {
			t.Errorf("text %d: got %d, reference %d", i, got, c.Tokens)
		}
	}
	for i, c := range fixtures.Requests {
		var req ClaudeRequest
		if err := json.Unmarshal(c.Request, &req); err != nil {
			t.Fatal(err)
		}
		if got := estimateClaudeRequestInputTokens(&req); got != c.Tokens {
			t.Errorf("request %d: got %d, reference %d", i, got, c.Tokens)
		}
	}
}

func TestSub2APIMeteringOutputUsesJoinedContentWithoutToolNames(t *testing.T) {
	tools := []KiroToolUse{{Name: "a_very_long_tool_name_that_is_not_generated_argument_content", Input: map[string]interface{}{"x": "hello"}}}
	want := estimateApproxTokens("thinkinganswer" + `{"x":"hello"}`)
	if got := estimateClaudeOutputTokens("answer", "thinking", tools); got != want {
		t.Fatalf("output fallback=%d want concatenated content %d", got, want)
	}
	_, got := finalizeUsageTokens(1, 7, 100, want)
	if got != 7 {
		t.Fatalf("native output must win: %d", got)
	}
}

func TestSub2APIMeteringOpenAIAndClaudeAgree(t *testing.T) {
	req := &OpenAIRequest{Messages: []OpenAIMessage{{Role: "user", Content: "Hello"}}}
	if got := estimateOpenAIRequestInputTokens(req); got != 14 {
		t.Fatalf("normalized request=%d, reference 14", got)
	}
}

func meteringTestInput(path, text string) int {
	// Integration tests use the request estimator whose independently generated
	// reference fixtures above pin the numeric contract.
	if path == "/v1/messages" {
		return estimateClaudeRequestInputTokens(&ClaudeRequest{Messages: []ClaudeMessage{{Role: "user", Content: text}}})
	}
	return estimateOpenAIRequestInputTokens(&OpenAIRequest{Messages: []OpenAIMessage{{Role: "user", Content: text}}})
}

func TestSub2APIMeteringObservedReasoningParity(t *testing.T) {
	for _, path := range []string{"/v1/messages", "/v1/chat/completions", "/v1/responses"} {
		for _, stream := range []bool{false, true} {
			for _, enabled := range []bool{false, true} {
				for _, native := range []bool{false, true} {
					t.Run(fmt.Sprintf("%s/%t/%t/%t", path, stream, enabled, native), func(t *testing.T) {
						h := newLegacyMeteringTestHandler(t, func(w http.ResponseWriter, r *http.Request) {
							if native {
								writeFrames(w, awsEventStreamFrame(t, "reasoningContentEvent", map[string]interface{}{"text": "I should carefully verify the result."}), awsEventStreamFrame(t, "assistantResponseEvent", map[string]interface{}{"content": "hello"}))
							} else {
								writeFrames(w, awsEventStreamFrame(t, "assistantResponseEvent", map[string]interface{}{"content": "<thinking>I should carefully verify the result.</thinking>hello"}))
							}
							_, _ = w.Write(meteringFrame(t))
						})
						model := "claude-sonnet-4.5"
						if enabled {
							model += "-thinking"
						}
						body := map[string]interface{}{"model": model, "stream": stream, "max_tokens": 256, "store": false}
						if path == "/v1/responses" {
							body["input"] = "Hello"
						} else {
							body["messages"] = []map[string]string{{"role": "user", "content": "Hello"}}
						}
						usage := runtimeProtocolUsage(t, localUsageJSONRequest(t, h, path, body, nil), stream)
						_, out, _, _ := localUsageTotals(path, usage)
						want := estimateApproxTokens("I should carefully verify the result.hello")
						if out != want {
							t.Fatalf("observed reasoning lost: got %d want %d", out, want)
						}
					})
				}
			}
		}
	}
}

func TestSub2APIMeteringOpenAIMultimodalNormalization(t *testing.T) {
	image := attachmentPNG(t, false)
	openai := &OpenAIRequest{Messages: []OpenAIMessage{{Role: "user", Content: []interface{}{map[string]interface{}{"type": "text", "text": "describe"}, map[string]interface{}{"type": "image_url", "image_url": map[string]interface{}{"url": "data:image/png;base64," + image}}}}, {Role: "assistant", Content: "a picture"}}}
	claude := &ClaudeRequest{Messages: []ClaudeMessage{{Role: "user", Content: []interface{}{map[string]interface{}{"type": "text", "text": "describe"}, map[string]interface{}{"type": "image", "source": map[string]interface{}{"type": "base64", "media_type": "image/png", "data": image}}}}, {Role: "assistant", Content: []interface{}{map[string]interface{}{"type": "text", "text": "a picture"}}}}}
	got, want := estimateOpenAIRequestInputTokens(openai), estimateClaudeRequestInputTokens(claude)
	if got != want {
		t.Fatalf("image normalization: %d want %d", got, want)
	}
	if got > 300 {
		t.Fatalf("encoded image data entered text count: %d", got)
	}
}

func TestSub2APIMeteringClaudeHostedInlineReasoning(t *testing.T) {
	for _, stream := range []bool{false, true} {
		t.Run(fmt.Sprint(stream), func(t *testing.T) {
			h := newLegacyMeteringTestHandler(t, func(w http.ResponseWriter, r *http.Request) {
				writeFrames(w, awsEventStreamFrame(t, "assistantResponseEvent", map[string]interface{}{"content": "<thinking>I should carefully verify the result.</thinking>hello"}), meteringFrame(t))
			})
			body := map[string]interface{}{"model": "claude-sonnet-4.5", "stream": stream, "max_tokens": 256, "thinking": map[string]string{"type": "disabled"}, "messages": []map[string]string{{"role": "user", "content": "Hello"}}, "tools": []ClaudeTool{nativeWebSearchTool()}}
			usage := runtimeProtocolUsage(t, localUsageJSONRequest(t, h, "/v1/messages", body, nil), stream)
			_, got, _, _ := localUsageTotals("/v1/messages", usage)
			if want := estimateApproxTokens("I should carefully verify the result.hello"); got != want {
				t.Fatalf("hosted output %d want %d", got, want)
			}
		})
	}
}
